import assert from 'node:assert/strict';
import {randomUUID} from 'node:crypto';
import {readFileSync} from 'node:fs';
import pg from 'pg';
import {other,home} from '../home-handoff-identifiers.mjs';
import {createGenerationFileCancellation} from '../../../lib/generation-file-cancellation.mjs';
import {createGenerationFileCopy,generationFileScopeDigest} from '../../../lib/generation-file-copy.mjs';
import {createHouseholdCopyStorage} from '../../../lib/closure-storage-runtime.mjs';
import {runWithTransactionCommitChecks} from '../../../lib/transaction-commit-checks.mjs';
import {createDeletionJournal} from '../kakei-completion/lib/shared-deletion-journal.mjs';

export async function verifyUnusedGenerationFileCancellation({admin,socket,bucket,reviewPort,file,bytes,projectID,secretKey,baseOptions,baseScope,getPosts,setCopyAdmission,setInspectionError,getInspections}){
 await admin.query('create role shared_retirement_backend login nosuperuser nobypassrls nocreatedb nocreaterole noreplication');
 await admin.query(readFileSync('tests/fixtures/generation-file-cancellation-20261021/protocol.sql','utf8'));
 await admin.query('grant select,update on private.kb_shared_deletion_journal to shared_retirement_backend;create policy file_cancel_roots on private.kb_shared_deletion_journal for all to shared_retirement_backend using(true) with check(true)');
 const coordinator=new pg.Client({host:socket,user:'shared_retirement_backend',database:'postgres'});await coordinator.connect();
 let loseCommit=false;
 const transaction=async work=>{await coordinator.query('begin');try{await coordinator.query("set local statement_timeout='4500ms'");const result=await runWithTransactionCommitChecks(coordinator,AbortSignal.timeout(10000),work);await coordinator.query('commit');if(loseCommit){loseCommit=false;throw Error('Synthetic lost cancelled-root COMMIT reply');}return result;}catch(e){await coordinator.query('rollback');throw e;}};
 try{
  const ownEpoch=randomUUID(),session=randomUUID();await admin.query('insert into auth.sessions(id,user_id) values($1,$2)',[session,other]);await admin.query('insert into maintenance_private.app_epochs values($1,$2,true)',[other,ownEpoch]);await admin.query('insert into maintenance_private.account_access values($1,true)',[other]);await admin.query('insert into maintenance_private.app_session_epochs values($1,$2,$3)',[session,other,ownEpoch]);await admin.query('insert into public.home_members("homeId",user_id,nickname) values($1,$2,$3)',[home,other,'Unused-copy cancellation actor']);
  await admin.query('set role service_role');const review=(await admin.query('select public.request_maintenance_closure_review($1,$2,$3,$4) receipt',[other,session,ownEpoch,randomUUID()])).rows[0].receipt.reviewRequestID;await admin.query('reset role');
  const storage=createHouseholdCopyStorage({projectID,secretKey});
  async function plan(source){source??=await file(other,ownEpoch);const r={userID:other,epochID:ownEpoch,reviewRequestID:review},signal=AbortSignal.timeout(15000),row=(await reviewPort.fileInventory({...r,afterFile:null},signal)).items.find(x=>x.attachment_id===source.id);const inspected=await reviewPort.inspectFile({...r,fileID:source.id,expectedMetadataDigest:row.metadata_digest,inspectionID:randomUUID()},signal),decisionID=randomUUID();await reviewPort.recordFileDecision({...r,fileID:source.id,inspectionID:inspected.inspectionID,decisionID,action:'retain_family_copy',evidenceDigest:'d'.repeat(64),confirmation:'RETAIN_REVIEWED_FAMILY_FILE_WITHOUT_DEPARTING_ACCOUNT_CONTENT_OR_PERSONAL_INFORMATION'},signal);return {source,input:{...r,intentID:randomUUID(),decisionID,fileID:source.id,destinationID:randomUUID()},signal};}
  let copyAllowed=true;
  async function make(){const scope={...baseScope,requestID:randomUUID(),userID:other,leaseToken:randomUUID(),apps:[{app:'ouchi-maintenance',requestID:randomUUID(),scopeID:ownEpoch}]},fixed={...scope};delete fixed.leaseToken;await admin.query("insert into private.kb_shared_deletion_journal values($1,$2,$3,'requested',null,null,'{}')",[scope.requestID,other,fixed]);const generationID=randomUUID(),nativeLease=randomUUID(),admission={domain:'OuchiMaintenance/generation-file-preparation-admission/v1',scopeDigest:generationFileScopeDigest(scope),generationID,nativeLease,reviewRequestID:review,confirmedUntil:new Date(Date.now()+300000).toISOString(),namespaceWriterDigest:'a'.repeat(64),reviewEvidenceDigest:'b'.repeat(64)};const copyOptions={...baseOptions,storage,scope,generationID,nativeLease,reviewRequestID:review,readAdmission:async()=>copyAllowed?admission:null},copy=createGenerationFileCopy(copyOptions);return {scope,generationID,nativeLease,copyOptions,copy};}
  const first=await make(),a=await plan(),b=await plan();await first.copy.prepare(a.input,a.signal);await first.copy.prepare(b.input,b.signal);
  const ids=[a.input.intentID,b.input.intentID],destinations=[a.input.destinationID,b.input.destinationID];
  let allowed=true,late=false,rejectContact=false;const cancel=createGenerationFileCancellation({...first,storage,verifyCancellationAdmission:async(_s,_tx,signal,phase)=>{signal.throwIfAborted();assert.ok(['preparing','committing'].includes(phase));return allowed;}});
  const snapshot=async()=>({root:(await admin.query('select * from private.kb_shared_deletion_journal where request_id=$1',[first.scope.requestID])).rows,header:(await admin.query('select * from maintenance_private.generation_file_preparations where generation_id=$1',[first.generationID])).rows,bindings:(await admin.query('select * from maintenance_private.generation_file_copy_bindings where generation_id=$1 order by intent_id',[first.generationID])).rows,intents:(await admin.query('select * from maintenance_private.household_copy_intents where intent_id=any($1) order by intent_id',[ids])).rows,destinations:(await admin.query('select * from maintenance_private.household_attachments where id=any($1) order by id',[destinations])).rows,capacity:(await admin.query('select * from maintenance_private.attachment_capacity_claims where claim_id=any($1) order by claim_id',[ids])).rows,tombstones:(await admin.query('select * from maintenance_private.retired_attachment_ids where attachment_id=any($1) order by attachment_id',[destinations])).rows,cancellations:(await admin.query('select * from maintenance_private.generation_file_preparation_cancellations where generation_id=$1',[first.generationID])).rows,sources:(await admin.query('select * from maintenance_private.product_attachments order by id')).rows,writes:(await admin.query('select * from maintenance_private.attachment_write_attempts order by attachment_id')).rows,auth:(await admin.query('select * from auth.sessions order by id')).rows,users:(await admin.query('select * from auth.users order by id')).rows,epochs:(await admin.query('select * from maintenance_private.app_epochs order by user_id,epoch_id')).rows,access:(await admin.query('select * from maintenance_private.account_access order by user_id')).rows,mappings:(await admin.query('select * from maintenance_private.app_session_epochs order by session_id')).rows,fences:(await admin.query('select * from maintenance_private.household_principal_fences order by user_id')).rows,home:(await admin.query('select * from public.homes where id=$1',[home])).rows,members:(await admin.query('select * from public.home_members where "homeId"=$1 order by user_id',[home])).rows});
  const before=await snapshot(),postsBefore=getPosts();
  const journal=createDeletionJournal({transaction:work=>transaction(async tx=>{await cancel.prepare(first.scope,tx);const result=await work(tx);if(late)allowed=false;return result;})},{'after-cancel':async()=>!rejectContact});
  await assert.rejects(transaction(tx=>tx.query("update private.kb_shared_deletion_journal set status='cancelled' where request_id=$1",[first.scope.requestID])),/not integrated with root transition/);
  allowed=false;await assert.rejects(journal.cancel(first.scope),/cancellation admission unavailable/);allowed=true;assert.deepEqual(await snapshot(),before);
  setInspectionError(true);await assert.rejects(journal.cancel(first.scope),/Storage read unconfirmed/);setInspectionError(false);assert.deepEqual(await snapshot(),before,'Unknown HTTP failures never mean absent and never remove preparation metadata');
  await admin.query('create table maintenance_private.cancel_unknown_child(intent uuid references maintenance_private.household_copy_intents(intent_id))');await assert.rejects(journal.cancel(first.scope),/Unused never-issued/);await admin.query('drop table maintenance_private.cancel_unknown_child');assert.deepEqual(await snapshot(),before,'Unknown child storage, even empty, cannot be silently cascaded');
  const moveID=randomUUID(),holdID=randomUUID();await admin.query('insert into maintenance_private.household_removal_capacity_moves values($1,$2,$3,$4,$5)',[a.input.destinationID,moveID,holdID,bytes.length,'a'.repeat(64)]);
  const moveBefore=(await admin.query('select * from maintenance_private.household_removal_capacity_moves where attachment_id=$1',[a.input.destinationID])).rows;await assert.rejects(journal.cancel(first.scope),/Unused never-issued/);assert.deepEqual((await admin.query('select * from maintenance_private.household_removal_capacity_moves where attachment_id=$1',[a.input.destinationID])).rows,moveBefore,'Known nonempty physical-move metadata is refused and preserved, never ignored');await admin.query('delete from maintenance_private.household_removal_capacity_moves where attachment_id=$1',[a.input.destinationID]);assert.deepEqual(await snapshot(),before);
  await assert.rejects(transaction(tx=>cancel.prepare(first.scope,tx)),/Current transaction verification/,'App-only undo cannot COMMIT without root cancellation');assert.deepEqual(await snapshot(),before);
  rejectContact=true;await assert.rejects(journal.cancel(first.scope),/cancellation persistence unconfirmed/);rejectContact=false;assert.deepEqual(await snapshot(),before,'Last independent contact refusal rolls metadata, tombstones, archive and root back');
  late=true;await assert.rejects(journal.cancel(first.scope),/Current transaction verification/);late=false;allowed=true;assert.deepEqual(await snapshot(),before);
  // Copy policy may be withdrawn; safe unused rollback has its own independent
  // cancellation authorization, never a renewal of the old copy approval.
  setCopyAdmission(false);copyAllowed=false;await assert.rejects(first.copy.copy({intentID:a.input.intentID,reviewRequestID:review,userID:other,epochID:ownEpoch},AbortSignal.timeout(5000)),/Independent finite/);loseCommit=true;await assert.rejects(journal.cancel(first.scope),/lost cancelled-root COMMIT reply/);setCopyAdmission(true);copyAllowed=true;
  const after=await snapshot();assert.equal(after.root[0].status,'cancelled');assert.equal(after.intents.length,0);assert.equal(after.destinations.length,0);assert.equal(after.cancellations.length,1);assert.equal(after.tombstones.length,2);assert.deepEqual(after.capacity,before.capacity);for(const key of ['header','bindings','sources','writes','auth','users','epochs','access','mappings','fences','home','members'])assert.deepEqual(after[key],before[key]);assert.equal(getPosts(),postsBefore,'Cancellation uses GET only; no physical upload/remove/release');
  const receipt=await transaction(tx=>cancel.readCancelled(first.scope,tx)),inspections=getInspections();assert.equal(receipt.fileCount,2);assert.equal(receipt.capacityReleased,false);assert.equal(receipt.accountErasureConfirmed,false);assert.deepEqual(await transaction(tx=>cancel.readCancelled(first.scope,tx)),receipt);assert.equal(getInspections(),inspections,'Lost COMMIT readback does not repeat Storage or metadata undo');
  for(const source of [a.source,b.source])assert.deepEqual(Buffer.from(await (await bucket.download(source.path)).data.arrayBuffer()),bytes);
  await assert.rejects(admin.query("insert into maintenance_private.household_attachments(id,home_id,home_instance_id,product_id,size_bytes,mime,sha256) select $1,home_id,home_instance_id,product_id,size_bytes,mime,sha256 from maintenance_private.household_attachments limit 1",[a.input.destinationID]),/Retired attachment identity/);
  await admin.query('begin');try{await admin.query('update maintenance_private.product_attachments set removal_pending=true where id=$1',[a.source.id]);}finally{await admin.query('rollback');}
  const next=await make(),nextPlan=await plan(a.source);await next.copy.prepare(nextPlan.input,nextPlan.signal);assert.notEqual(nextPlan.input.intentID,a.input.intentID);assert.deepEqual(await transaction(tx=>cancel.readCancelled(first.scope,tx)),receipt,'Old fact remains readable after reapplication, never unfreezes it');
  await assert.rejects(admin.query('update maintenance_private.product_attachments set removal_pending=true where id=$1',[a.source.id]),/Pending household copy/);
  await assert.rejects(transaction(tx=>cancel.prepare(first.scope,tx)),/Unused never-issued/);
  // A real destination with no claimed writer is NOT cleaned up or relabeled as
  // unused. It remains held for separate provider/ownership reconciliation.
  const dest=(await admin.query('select object_path from maintenance_private.household_attachments where id=$1',[nextPlan.input.destinationID])).rows[0].object_path;
  const nextCancel=createGenerationFileCancellation({...next,storage,verifyCancellationAdmission:async()=>true}),nextBefore=(await admin.query('select * from maintenance_private.household_copy_intents where intent_id=$1',[nextPlan.input.intentID])).rows;
  const latePhysical=createDeletionJournal({transaction:work=>transaction(async tx=>{await nextCancel.prepare(next.scope,tx);const result=await work(tx);assert.equal((await bucket.upload(dest,bytes,{contentType:'application/pdf',upsert:false})).error,null);return result;})},{'after-cancel':async()=>true});
  await assert.rejects(latePhysical.cancel(next.scope),/Current transaction verification/,'A real destination appearing after metadata undo refuses final COMMIT and restores the complete preparation');assert.deepEqual((await admin.query('select * from maintenance_private.household_copy_intents where intent_id=$1',[nextPlan.input.intentID])).rows,nextBefore);assert.equal((await admin.query('select count(*)::int n from maintenance_private.generation_file_preparation_cancellations where generation_id=$1',[next.generationID])).rows[0].n,0);
  const readsBefore=getInspections();await assert.rejects(transaction(tx=>nextCancel.prepare(next.scope,tx)),/Unused never-issued/);assert.equal(getInspections(),readsBefore);assert.equal((await admin.query('select status from private.kb_shared_deletion_journal where request_id=$1',[next.scope.requestID])).rows[0].status,'requested');assert.equal((await bucket.download(dest)).error,null);
  const mixed=createGenerationFileCancellation({...baseOptions,storage,verifyCancellationAdmission:async()=>true});await assert.rejects(transaction(tx=>mixed.prepare(baseScope,tx)),/Unused never-issued/,'ANY dispatched/acknowledged/verified file prevents WHOLE-root file cancellation');assert.equal((await admin.query('select status from private.kb_shared_deletion_journal where request_id=$1',[baseScope.requestID])).rows[0].status,'requested');assert.equal(getPosts(),postsBefore);
  await assert.rejects(coordinator.query('select * from maintenance_private.generation_file_preparation_cancellations'),/permission denied/);assert.equal((await admin.query('select count(*)::int n from maintenance_private.generation_file_cancellation_contexts')).rows[0].n,0);
  console.log('Unused generation file cancellation: actual normal journal cancellation with two NEVER-ISSUED copies, fixed source hashes + genuine official Storage NoSuchKey + metadata absence before undo and before COMMIT. Exact staged metadata only removed, both unused destination IDs retired, original capacity/bindings/header/source/family/synthetic Auth preserved. Missing authorization/HTTP failure/unknown child/partial-root/contact/late failure roll ALL back. Lost root COMMIT acknowledgement recovers same immutable fact without I/O; same-source/new-root reapply works, old fact cannot unfreeze it. Any dispatched/verified copy or unexpected existing destination refuses WHOLE cancellation without Storage mutation. NO real paired public cancellation/active file erasure/capacity release/production adoption.');
 }finally{await coordinator.end();}
}
